// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowLeftIcon,
  ArrowRightIcon,
  ArrowRightLeftIcon,
  EyeIcon,
  FileArchiveIcon,
  FileDownIcon,
  FilePenLineIcon,
  ImageIcon,
  ImagesIcon,
  RotateCwIcon,
  ScanSearchIcon,
  XIcon,
} from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, MODES, ORDER, PDF_MODE, ROTATE, SCANS, SETUP, TITLE } from './script'

const MODE_ICONS = [
  ArrowRightLeftIcon,
  FilePenLineIcon,
  ImagesIcon,
  FileArchiveIcon,
  ScanSearchIcon,
  EyeIcon,
]

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  W,
  step,
  final,
  move,
  click,
  type,
  count,
  wait,
  cursorOut,
}) => {
  step(0)
  move(`mode-${PDF_MODE}`, { at: 0.3 })
  click(`mode-${PDF_MODE}`)
  tl.to(q('mode-0'), { backgroundColor: 'rgba(255,255,255,0)', duration: 0.2 }, '<')
  tl.to(q(`mode-${PDF_MODE}`), { backgroundColor: 'rgba(244,63,94,0.16)', duration: 0.2 }, '<')
  tl.fromTo(q('drop'), { opacity: 0 }, { opacity: 1, duration: 0.3, immediateRender: false }, '<')

  step(1, '+=0.4')
  const target = pos('drop', 0.5, 0.45)
  SCANS.forEach((_, index) => {
    tl.fromTo(
      q(`flyer-${index}`),
      { x: W - 40 + index * 10, y: -40, rotate: 12, opacity: 1 },
      {
        x: target.x - 18 + (index - 1) * 26,
        y: target.y - 22,
        rotate: (index - 1) * 6,
        duration: 0.7,
        ease: 'power3.out',
        immediateRender: false,
      },
      index === 0 ? '>' : '<0.12',
    )
  })
  tl.to(q('drop'), { borderColor: '#f43f5e', duration: 0.2 }, '<0.3')
  tl.to([...qa('flyer'), q('drop')], { opacity: 0, duration: 0.25 }, '+=0.2')
  tl.fromTo(q('pages'), { opacity: 0 }, { opacity: 1, duration: 0.3, immediateRender: false }, '<')
  tl.fromTo(
    qa('card'),
    { opacity: 0, y: 12, scale: 0.9 },
    {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 0.4,
      stagger: 0.1,
      ease: 'back.out(2)',
      immediateRender: false,
    },
    '<',
  )

  step(2, '+=0.5')
  move(`rotate-${ROTATE}`)
  click(`rotate-${ROTATE}`)
  tl.to(q(`thumb-${ROTATE}`), { rotate: 90, duration: 0.45, ease: 'back.out(1.6)' }, '<')
  const moved = ORDER.findIndex((source, index) => source !== index)
  const from = ORDER[moved]
  move(`earlier-${from}`)
  click(`earlier-${from}`)
  const pitch = pos(`card-${from}`).x - pos(`card-${moved}`).x
  tl.to(q(`card-${from}`), { x: -pitch, duration: 0.45, ease: 'power3.inOut' }, '<')
  tl.to(q(`card-${moved}`), { x: pitch, duration: 0.45, ease: 'power3.inOut' }, '<')
  tl.set(q(`num-${from}`), { text: String(moved + 1) }, '<0.2')
  tl.set(q(`num-${moved}`), { text: String(from + 1) }, '<')

  step(3, '+=0.5')
  move('title', { ax: 0.2 })
  click('title')
  tl.to(q('title-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('title-text', TITLE, { speed: 0.04 })
  move('build')
  click('build')
  tl.set(q('build-label'), { opacity: 0 }, '<')
  tl.set(q('preparing'), { opacity: 1 }, '<')
  count('prep-done', SCANS.length, { from: 1, at: '<', duration: 0.8, ease: 'none' })
  tl.fromTo(
    q('preview'),
    { opacity: 0, scale: 0.96 },
    { opacity: 1, scale: 1, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '>',
  )
  tl.fromTo(
    qa('pdf-page'),
    { y: 30, opacity: 0 },
    { y: 0, opacity: 1, duration: 0.45, stagger: 0.12, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)

  tl.set([q('drop'), q('pages'), q('preview'), q('preparing'), ...qa('flyer')], { opacity: 0 }, 0)
}

function Scan({ index, className }: { index: number; className?: string }) {
  const scan = SCANS[index]
  const landscape = scan.width > scan.height
  return (
    <span
      className={`flex flex-col gap-[3px] rounded-sm bg-white p-1 shadow ${landscape ? 'h-8 w-11' : 'h-11 w-8'} ${className ?? ''}`}
    >
      <span className="block h-1 w-2/3 rounded-full" style={{ background: scan.tint }} />
      {[0, 1, 2].map((line) => (
        <span key={line} className="block h-0.5 w-full rounded-full bg-black/15" />
      ))}
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`File Toolkit combining ${SCANS.length} receipt scans into one PDF: rotating a sideways scan, reordering pages and previewing the result`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div className="grid grid-cols-6 gap-1">
            {MODES.map((mode, index) => {
              const Icon = MODE_ICONS[index]
              return (
                <span
                  key={mode.label}
                  data-d={`mode-${index}`}
                  title={mode.hint}
                  className={`flex flex-col items-center gap-0.5 rounded-lg border border-line px-1 py-1 text-center ${index === 0 ? 'bg-white/[0.08]' : ''}`}
                >
                  <Icon className="size-3.5 text-ink-soft" />
                  <span className="text-[8.5px] font-semibold leading-tight text-ink">
                    {mode.label}
                  </span>
                </span>
              )
            })}
          </div>
          <div className="relative min-h-0 flex-1">
            <div
              data-d="drop"
              className="absolute inset-0 flex flex-col items-center justify-center gap-1 rounded-xl border-2 border-dashed border-line-strong opacity-0"
            >
              <ImageIcon className="size-6 text-muted" />
              <p className="text-[11px] font-semibold text-ink">
                Drop images to combine into a PDF
              </p>
              <p className="text-[9px] text-muted">
                Each image becomes one page. You can reorder and rotate them next.
              </p>
            </div>
            <div data-d="pages" className="absolute inset-0 flex flex-col gap-1.5 opacity-0">
              <div className="rounded-lg border border-line p-1.5">
                <div className="grid grid-cols-4 gap-1.5">
                  {SETUP.map((option) => (
                    <span key={option.label}>
                      <span className="block text-[7.5px] text-muted">{option.label}</span>
                      <span className="block truncate rounded border border-line-strong px-1.5 py-0.5 text-[8.5px] text-ink">
                        {option.value}
                      </span>
                    </span>
                  ))}
                </div>
                <span
                  data-d="title"
                  className="relative mt-1.5 flex h-5 items-center rounded border border-line-strong px-1.5 text-[8.5px]"
                >
                  <span data-d="title-ph" className="absolute left-1.5 text-muted">
                    PDF title (optional)
                  </span>
                  <span data-d="title-text" className="text-ink" />
                </span>
              </div>
              <div className="rounded-lg border border-line p-1.5">
                <p className="text-[9.5px] font-semibold text-ink">Pages ({SCANS.length})</p>
                <div className="mt-1 grid grid-cols-4 gap-2">
                  {SCANS.map((scan, index) => (
                    <div
                      key={scan.name}
                      data-d={`card card-${index}`}
                      className="flex flex-col gap-0.5 rounded-lg border border-line bg-white/[0.03] p-1"
                    >
                      <span className="relative flex h-12 items-center justify-center rounded-md bg-white/[0.06]">
                        <span data-d={`thumb-${index}`} className="flex">
                          <Scan index={index} />
                        </span>
                        <span
                          data-d={`num-${index}`}
                          className="absolute left-1 top-1 rounded bg-canvas px-1 text-[7.5px] font-bold text-ink"
                        >
                          {index + 1}
                        </span>
                      </span>
                      <span className="truncate text-[8px] font-medium text-ink">{scan.name}</span>
                      <span className="text-[7.5px] tabular-nums text-muted">
                        {scan.width}×{scan.height} · {scan.size}
                      </span>
                      <span className="flex justify-between text-ink-soft">
                        <ArrowLeftIcon data-d={`earlier-${index}`} className="size-2.5" />
                        <RotateCwIcon data-d={`rotate-${index}`} className="size-2.5" />
                        <ArrowRightIcon className="size-2.5" />
                        <XIcon className="size-2.5" />
                      </span>
                    </div>
                  ))}
                </div>
              </div>
              <div className="mt-auto flex items-center gap-2 rounded-xl border border-line p-1.5">
                <span
                  data-d="build"
                  className="relative flex h-6 items-center gap-1 rounded-md bg-ink px-2.5 text-[9.5px] font-semibold text-canvas"
                >
                  <FileDownIcon className="size-3" />
                  <span data-d="build-label">Build PDF · {SCANS.length} pages</span>
                  <span data-d="preparing" className="absolute left-7 opacity-0">
                    Preparing image <span data-d="prep-done">1</span> of {SCANS.length}…
                  </span>
                </span>
                <span className="ml-auto text-[8.5px] tabular-nums text-muted">
                  {SCANS.length} pages
                </span>
              </div>
            </div>
            <div
              data-d="preview"
              className="absolute inset-0 flex flex-col items-center justify-center gap-2 rounded-xl border border-line-strong bg-[#101016] opacity-0 shadow-2xl"
            >
              <div className="flex items-end gap-2">
                {ORDER.map((source, page) => (
                  <span
                    key={source}
                    data-d="pdf-page"
                    className="flex h-[92px] w-[66px] items-center justify-center rounded-sm bg-white p-1.5 shadow-lg"
                  >
                    <span className={source === ROTATE ? 'rotate-90' : ''}>
                      <Scan index={source} />
                    </span>
                    <span className="sr-only">Page {page + 1}</span>
                  </span>
                ))}
              </div>
              <p className="text-[10.5px] font-semibold text-ink">{TITLE}.pdf</p>
              <p className="text-[8.5px] text-muted">PDF · {SCANS.length} pages · A4</p>
            </div>
          </div>
        </div>
      </PanelChrome>
      {SCANS.map((scan, index) => (
        <span
          key={scan.name}
          data-d={`flyer flyer-${index}`}
          className="absolute left-0 top-0 z-20 opacity-0"
        >
          <Scan index={index} />
        </span>
      ))}
    </DemoStage>
  )
}
